arguments.content:
.PHONY: all clean help

# Default target
all: help

help:
	@echo "Common targets:"
	@echo "  all    - default (prints help)"
	@echo "  clean  - remove common build/test/cache artifacts"
	@echo "  help   - show this message"

clean:
	@echo "Cleaning..."
	@rm -rf \
		build dist out \
		*.o *.obj *.a *.so *.dylib *.dll \
		*.exe *.app \
		*.log \
		__pycache__ .pytest_cache .mypy_cache .ruff_cache \
		.coverage coverage.xml htmlcov \
		.node_modules node_modules \
		.cache .cache \
		.DS_Store

