arguments.newText:
.PHONY: all clean help log-env

# Default target
all: log-env help

log-env:
	@echo "Environment:"
	@echo "  PWD=$$(pwd)"
	@echo "  USER=$${USER:-}"
	@echo "  SHELL=$${SHELL:-}"
	@echo "  PATH=$${PATH:-}"
	@echo "  MAKEFLAGS=$${MAKEFLAGS:-}"
	@echo "  MAKELEVEL=$${MAKELEVEL:-}"

help:
	@echo "Common targets:"
	@echo "  all      - default (prints env + help)"
	@echo "  log-env  - print a few useful environment variables"
	@echo "  clean    - remove common build/test/cache artifacts"
	@echo "  help     - show this message"

